# Generated by manage.py generate_test_cases.
"""Rich-text widget identity and options survive Django's form-field rendering."""

from bs4 import BeautifulSoup
from django.template import Context, Template
from django_cotton.compiler_regex import CottonCompiler

from bloomerp.tests.base import BloomerpWidgetTestCase, WidgetOperation, WidgetScenario
from bloomerp.widgets.text_editor import BloomerpTextEditorWidget


class TestBloomerpTextEditorWidget(BloomerpWidgetTestCase):
    """Verify generic editor identity and border options in the rendered markup."""

    widget_class = BloomerpTextEditorWidget

    def get_test_scenarios(self) -> list[WidgetScenario[BloomerpTextEditorWidget]]:
        """Cover generic editor registration, border options, and render overrides."""
        return [
            WidgetScenario(
                name="Generic editors use their own component without feature context",
                operations=[
                    WidgetOperation(
                        name="Render generic editor",
                        execute=self.render_editor,
                        result_validators=self.has_generic_editor,
                    )
                ],
            ),
            WidgetScenario(
                name="Cotton editors ignore unrelated outer component names",
                operations=[
                    WidgetOperation(
                        name="Render editor within another component's context",
                        execute=self.render_with_outer_component_name,
                        result_validators=self.has_generic_editor,
                    )
                ],
            ),
            WidgetScenario(
                name="Field-configured border survives bound-field rendering attributes",
                constructor_kwargs={"attrs": {"has_border": True}},
                operations=[
                    WidgetOperation(
                        name="Render editor",
                        execute=self.render_editor,
                        result_validators=self.has_border,
                    )
                ],
            ),
            WidgetScenario(
                name="Render-time false overrides the configured border",
                constructor_kwargs={"attrs": {"has_border": True}},
                operations=[
                    WidgetOperation(
                        name="Render borderless override",
                        execute=self.render_borderless,
                        result_validators=self.has_no_border,
                    )
                ],
            ),
            WidgetScenario(
                name="Existing widgets remain borderless by default",
                operations=[
                    WidgetOperation(
                        name="Render editor",
                        execute=self.render_editor,
                        result_validators=self.has_no_border,
                    )
                ],
            ),
        ]

    def render_editor(self, widget: BloomerpTextEditorWidget) -> str:
        """Simulate the ID attributes Django supplies when rendering a bound form field."""
        return str(
            widget.render("content", "Meeting notes", attrs={"id": "id_content"})
        )

    def render_borderless(self, widget: BloomerpTextEditorWidget) -> str:
        """Override the constructor's border through explicit render-time attributes."""
        return str(
            widget.render(
                "content",
                "Meeting notes",
                attrs={"id": "id_content", "has_border": False},
            )
        )

    def render_with_outer_component_name(
        self, widget: BloomerpTextEditorWidget
    ) -> str:
        """Render the shared Cotton input without inheriting a parent's component ID."""
        context = widget.get_context("content", "Meeting notes", None)
        context["component_name"] = "unrelated"
        source = CottonCompiler().process(
            '<c-ui.inputs.text_editor name="{{ name }}" value="{{ value }}" />'
        )
        return Template(source).render(Context(context))

    def has_generic_editor(self, html: str) -> bool:
        """Keep ordinary rich-text widgets separate from document-template editors."""
        markup = BeautifulSoup(html, "html.parser")
        editor = markup.select_one('[bloomerp-component="bloomerp-text-editor"]')
        self.assertIsNotNone(editor)
        self.assertIsNone(markup.select_one("[data-editor-context]"))
        self.assertIsNone(
            markup.select_one('[bloomerp-component="document-template-text-editor"]')
        )
        return True

    def has_border(self, html: str) -> bool:
        """Require the shared editor container's border classes in rendered markup."""
        return "border border-gray-300" in html

    def has_no_border(self, html: str) -> bool:
        """Preserve explicitly or implicitly borderless editor rendering."""
        return "border border-gray-300" not in html
